157	        service.changeStatus("INC-A", "alice", new StatusRequest(key(), "CONTAINED"));
158	
159	        // 并发：完成唯一 OPEN 任务与推进 RESOLVED（解决门禁要求无 OPEN 任务）
160	        List<Object> results = runConcurrently(List.of(
161	                () -> service.completeTask("INC-A", "T-1", "alice", new TaskActionRequest(key())),
162	                () -> service.changeStatus("INC-A", "alice", new StatusRequest(key(), "RESOLVED"))));
163	
164	        // 任务完成必然成功；解决仅在完成先提交时通过门禁
165	        TaskView task = service.getTask("INC-A", "T-1");
166	        assertThat(task.status()).isEqualTo("DONE");
167	        IncidentView end = service.get("INC-A");
168	        Object resolveResult = results.get(1);
169	        if ("RESOLVED".equals(end.status())) {
170	            assertThat(resolveResult).isInstanceOf(IncidentView.class);
171	        } else {
172	            // 解决先评估：仍有 OPEN 任务，门禁 409
173	            assertThat(end.status()).isEqualTo("CONTAINED");
174	            assertThat(resolveResult).isInstanceOfSatisfying(ApiException.class,
175	                    e -> assertThat(e.status()).isEqualTo(HttpStatus.CONFLICT));
176	        }
177	    }
