190	        List<TaskView> successes = results.stream().filter(TaskView.class::isInstance)
191	                .map(TaskView.class::cast).toList();
192	        assertThat(successes).isNotEmpty();
193	        // 所有成功响应一致，且任务只创建一次
194	        assertThat(successes).allSatisfy(v -> assertThat(v).isEqualTo(successes.get(0)));
195	        assertThat(service.listTasks("INC-A").tasks()).hasSize(1);
196	        Integer keyCount = jdbc.queryForObject(
197	                "SELECT COUNT(*) FROM command_keys WHERE command_key = ?", Integer.class,
198	                commandKey);
199	        assertThat(keyCount).isEqualTo(1);
200	    }
201	
202	    @Test
203	    void concurrentCreate_max20Enforced() throws Exception {
204	        commanding("INC-A", "alice");
205	        List<Callable<TaskView>> tasks = new ArrayList<>();
206	        for (int i = 1; i <= 25; i++) {
207	            String taskKey = "T-" + i;
208	            tasks.add(() -> service.createTask("INC-A", "alice",
209	                    new TaskCreateRequest(key(), taskKey, "G", "任务" + taskKey, List.of())));
210	        }
211	        List<Object> results = runConcurrently(tasks);
212	
213	        long successes = results.stream().filter(TaskView.class::isInstance).count();
214	        assertThat(successes).isEqualTo(20);
215	        assertThat(countConflicts(results)).isEqualTo(5);
216	        assertThat(service.listTasks("INC-A").tasks()).hasSize(20);
217	    }
