        mergeOk("PLAN-14", "alice", mergeBody("REQ-14A", "MG-14A", 1, left, right, 1, 1, List.of()));
        mvc.perform(post("/api/plans/{k}/revisions", "PLAN-14")
                        .header("X-Actor-Id", "alice")
